import java.util.function.Consumer;
import java.util.function.Function;

class MyClass {
    private static String staticState = "";
    private String instanceState = "";

    public static void setStaticState(String s) {
        staticState = s;
    }

    public void setInstanceState(String s) {
        this.instanceState = s;
    }

    public void process(String data) {
        // Does not match: lambda calls static method
        Consumer<String> c1 = s -> MyClass.setStaticState(s);

        // Does not match: lambda calls method on another object
        MyClass another = new MyClass();
        Consumer<String> c2 = s -> another.setInstanceState(s);

        // Does not match: lambda has no arguments
        Runnable r = () -> this.setInstanceState("fixed");

        // Does not match: lambda argument is not directly passed or transformed
        Consumer<String> c3 = s -> this.setInstanceState(s + "_processed");

        // Does not match: block lambda
        Consumer<String> c4 = s -> {
            System.out.println("Processing " + s);
            this.setInstanceState(s);
        };

        // Does not match: lambda argument is the receiver
        Function<String, Integer> f1 = s -> s.length();
    }
}

